<script setup lang="ts">import {ref,computed} from 'vue';import type {Workspace} from '../stores/workspace';import type {CriterionMeta} from '../types/domain';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import {create} from '../api/criteria';import {useAsync} from '../hooks/useAsync';import {DIRECTIONS} from '../constants/enums';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const name=ref(''),dataset=ref(''),directions=ref<Record<string,'cost'|'benefit'>>({});const ds=computed(()=>props.data.datasets.find(d=>d.id===dataset.value)||props.data.datasets[0]);const {busy,error,execute}=useAsync();const direction=(code:string)=>directions.value[code]||(code==='cost'||code==='hours'?'cost':'benefit');async function submit(){await execute(async()=>{await create({name:name.value,dataset_id:ds.value?.id,criteria:ds.value?.columns.map(c=>({code:c.code,direction:direction(c.code)}))});name.value='';await props.refresh()})};</script><template><PageHeading code="03 / CRITERION DIRECTIONS" title="越小越优，还是越大越优？" description="方向改变理想点。指标顺序也就是下一页判断矩阵的行列顺序，锁定后保留原口径。"/><section class="paper" v-if="canWrite"><h2>锁定指标方向</h2><form class="grid-form" @submit.prevent="submit"><label>口径名称<input aria-label="口径名称" required minlength="2" v-model="name"/></label><label>方案集<select aria-label="指标方案集" v-model="dataset"><option value="" disabled>默认使用最新方案集</option><option v-for="d in data.datasets" :key="d.id" :value="d.id">{{d.name}}</option></select></label><div class="wide direction-editor"><label v-for="(c,i) in ds?.columns" :key="c.code"><span>{{i+1}} / {{c.label}} · {{c.unit}}</span><select :aria-label="c.code+'方向'" :value="direction(c.code)" @change="directions[c.code]=($event.target as HTMLSelectElement).value as 'cost'|'benefit'"><option value="cost">成本型 · 越小越优</option><option value="benefit">收益型 · 越大越优</option></select></label></div><Notice v-if="error" error>{{error}}</Notice><button :disabled="busy">保存指标方向</button></form></section><section class="paper" v-for="c in data.criteria" :key="c.id"><div class="section-heading"><h2>{{c.name}}</h2><span>{{data.datasets.find(d=>d.id===c.dataset_id)?.name}}</span></div><div class="direction-strip"><div v-for="(x,i) in c.criteria" :key="x.code"><b>{{i+1}}</b><span>{{data.datasets.find(d=>d.id===c.dataset_id)?.columns.find(v=>v.code===x.code)?.label}}</span><small :class="x.direction">{{DIRECTIONS[x.direction]}}</small></div></div></section></template>
